# views.py - Django REST Framework GraphQL proxy endpoint
import json
import requests
from django.http import JsonResponse, HttpResponse
from django.views.decorators.csrf import csrf_exempt
from django.utils.html import escape
from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated

GRAPHQL_BACKEND = "http://internal-graphql:4000/graphql"

@csrf_exempt
@api_view(['POST', 'GET'])
@permission_classes([IsAuthenticated])
def graphql_proxy(request):
    """Proxy GraphQL queries to internal service with error reporting UI"""
    if request.method == 'GET':
        # Serve GraphQL explorer with user's last query pre-filled
        last_query = request.session.get('last_graphql_query', '')
        # Render inline for developer convenience
        html = f"""<!DOCTYPE html>
<html>
<head><title>GraphQL Explorer</title></head>
<body>
<div id="app">
<h1>GraphQL Explorer</h1>
<textarea id="query" rows="10" cols="80">{last_query}</textarea>
<button onclick="executeQuery()">Run</button>
<pre id="result"></pre>
</div>
<script>
function executeQuery() {{
    const query = document.getElementById('query').value;
    fetch('/api/graphql/', {{
        method: 'POST',
        headers: {{'Content-Type': 'application/json'}},
        body: JSON.stringify({{query: query}})
    }}).then(r => r.json()).then(d => {{
        document.getElementById('result').textContent = JSON.stringify(d, null, 2);
    }});
}}
</script>
</body></html>"""
        return HttpResponse(html, content_type='text/html')

    # POST: forward GraphQL query to backend
    try:
        body = json.loads(request.body)
    except json.JSONDecodeError:
        return JsonResponse({'error': 'Invalid JSON'}, status=400)

    query = body.get('query', '')
    variables = body.get('variables', {})
    operation_name = body.get('operationName', None)

    # Store for explorer pre-fill
    request.session['last_graphql_query'] = query

    # Basic introspection blocking (security measure)
    if '__schema' in query or '__type' in query:
        return JsonResponse({'error': 'Introspection disabled'}, status=403)

    # Forward to internal GraphQL service
    try:
        resp = requests.post(
            GRAPHQL_BACKEND,
            json={
                'query': query,
                'variables': variables,
                'operationName': operation_name
            },
            headers={
                'X-Forwarded-User': request.user.username,
                'X-Request-ID': request.META.get('HTTP_X_REQUEST_ID', ''),
            },
            timeout=30
        )
        result = resp.json()
    except requests.exceptions.Timeout:
        return JsonResponse({'error': 'Backend timeout'}, status=504)
    except Exception as e:
        return JsonResponse({'error': str(e)}, status=502)

    # If there are GraphQL errors, render them in a debug page
    if 'errors' in result and request.user.is_staff:
        error_messages = result['errors']
        # Render error detail page with query context for debugging
        error_html = f"""<!DOCTYPE html>
<html><head><title>GraphQL Error</title></head>
<body>
<h1>GraphQL Errors</h1>
<h3>Query:</h3>
<pre>{query}</pre>
<h3>Errors:</h3>
<pre>{json.dumps(error_messages, indent=2)}</pre>
<script>console.log('Debug: query was: ' + {json.dumps(query)})</script>
</body></html>"""
        return HttpResponse(error_html, content_type='text/html')

    return JsonResponse(result, status=resp.status_code)


@api_view(['GET'])
@permission_classes([IsAuthenticated])
def graphql_schema_docs(request):
    """Return cached schema documentation"""
    from django.core.cache import cache
    docs = cache.get('graphql_schema_docs')
    if not docs:
        return JsonResponse({'error': 'Schema docs not cached'}, status=404)
    return JsonResponse({'docs': docs})
